def _collapse_dims(t):
    """Collapse dims that are contiguous in memory; drop size-1 dims.

    Dims are listed outermost first.  Two neighbours collapse when the outer
    stride equals the span of the inner dim; the merged dim then walks memory
    with the *inner* stride.
    """
    dims = [[sz, st] for sz, st in zip(t.shape, t.stride()) if sz != 1]
    i = len(dims) - 1
    while i > 0:
        inner = dims[i]
        outer = dims[i - 1]
        if outer[1] == inner[0] * inner[1]:
            outer[0] *= inner[0]
            outer[1] = inner[1]
            del dims[i]
        i -= 1
    return dims


def _launch_strided(t, numel, f64):
    dims = _collapse_dims(t)
    if len(dims) > _MAX_DIMS:
        # Absurdly deep rank: peel the outermost dim with zero-copy views.
        for i in range(t.shape[0]):
            sub = t[i]
            _launch_strided(sub, sub.numel(), f64)
        return
    grid = ((numel + _BLOCK - 1) // _BLOCK,)
    pad = _MAX_DIMS - len(dims)
    sh = [d[0] for d in dims] + [1] * pad
    st = [d[1] for d in dims] + [0] * pad
    _log10_strided_kernel[grid](t, numel, *sh, *st, F64=f64, BLOCK=_BLOCK)


